285: ///
286: /// Returns whether it compiled without errors.
287: #[typst_macros::time(name = "compile once")]
288: pub fn compile_once(
289:     world: &mut SystemWorld,
290:     config: &mut CompileConfig,
291: ) -> HintedStrResult<()> {
292:     let start = std::time::Instant::now();
293:     if config.watching {
294:         Status::Compiling.print(config).unwrap();
295:     }
296: 
297:     let Warned { output, mut warnings } = compile_and_export(world, config);
298: 
299:     // Add static warnings (for deprecated CLI flags and such).
300:     for warning in &config.warnings {
301:         warnings.push(warning.clone().into_warning_at(Span::detached()));
302:     }
303: 
304:     match &output {
305:         // Print success message and possibly warnings.
306:         Ok(_) => {
307:             let duration = start.elapsed();
308:             if config.watching {
309:                 if warnings.is_empty() {
310:                     Status::Success(duration).print(config).unwrap();
311:                 } else {
312:                     Status::PartialSuccess(duration).print(config).unwrap();
313:                 }
314:             }
315: 
316:             print_diagnostics(world, &[], &warnings, config.diagnostic_format)
317:                 .map_err(|err| eco_format!("failed to print diagnostics ({err})"))?;
318: 
319:             open_output(config)?;
320:         }
321: 
322:         // Print failure message and diagnostics.
323:         Err(errors) => {
324:             set_failed();
325: 
326:             if config.watching {
327:                 Status::Error.print(config).unwrap();
328:             }
329: 
330:             print_diagnostics(world, errors, &warnings, config.diagnostic_format)
331:                 .map_err(|err| eco_format!("failed to print diagnostics ({err})"))?;
332:         }
333:     }
334: 
335:     if let Some(dest) = &config.deps {
336:         write_deps(world, dest, config.deps_format, output.as_deref().ok())
337:             .map_err(|err| eco_format!("failed to create dependency file ({err})"))?;
338:     }
339: 
340:     Ok(())
341: }
