/// Export to a PDF.
fn export_pdf(
    document: &PagedDocument,
    config: &CompileConfig,
) -> Warned<SourceResult<()>> {
    let options = pdf_options(config);
    typst_pdf::pdf(document, &options).and_then(|buffer| {
        config
            .output
            .write(&buffer)
            .map_err(|err| eco_format!("failed to write PDF file ({err})"))
            .at(Span::detached())?;
        Ok(())
    })
}

